ISHARES_REFERENCE_COUNT=225


def add_ishares_screenshots(html: str):
    # The existing emitted quote script is read inside the HTML. Remove the
    # unavailable tile from its render function rather than CSS-hiding one row.
    unwanted="etfStatistic(stats,'Bid-offer spread','Unavailable','No validated live two-way quotes');"
    html=html.replace(unwanted,'')
    # The new inventory sits after fund detail, before the ETF panel's closing tag.
    if 'id="mt-ishares-screenshot-register"' not in html:
        panel_start=html.find('<section class="panel" id="etf-tracker-panel"')
        audit_start=html.find('<section class="panel" id="etf-audit-panel"')
        quality_start=html.find('<section class="panel" id="quality-panel"')
        next_panel=audit_start if audit_start>panel_start else quality_start
        if panel_start<0 or next_panel<=panel_start:
            raise ValueError('ETF panel boundary changed; not adding screenshot catalogue')
        end=html.rfind('</section>',panel_start,next_panel)
        if end<0:raise ValueError('ETF panel closing tag not found')
        html=html[:end]+ISHARES_REFERENCE_PANEL+'\n'+html[end:]
    css_open='<style id="mt-ishares-screenshots-css">'
    if css_open not in html:
        html=html.replace('</head>',css_open+ISHARES_REFERENCE_CSS+'</style>\n</head>',1)
    script_open='<script id="mt-ishares-screenshots-js">'
    if script_open not in html:
        if html.count('</body>')!=1:raise ValueError('Expected exactly one HTML body close')
        html=html.replace('</body>',script_open+ISHARES_REFERENCE_JS+'</script>\n</body>',1)
    return html



