def add_audit_and_amundi(html:str)->str:
    if 'id="mt-amundi-screenshot-register"' in html:
        return html
    # Put audit metadata immediately after the embedded market snapshot, before
    # the dashboard's chart/render definitions execute. Do not rewrite the 50 MB
    # JSON snapshot or any price/quote/historical observations.
    mark='window.MT_DATA = '
    i=html.find(mark)
    if i<0:raise ValueError('Market snapshot placeholder absent')
    end=html.find('</script>',i)
    if end<0:raise ValueError('Market snapshot script close absent')
    insert='\n<script id="mt-etf-2026-audit-preload">'+AUDIT_PRELOAD_JS+'</script>'
    html=html[:end+len('</script>')]+insert+html[end+len('</script>'):]
    html=html.replace(insert,insert+'\n<script id="mt-issuer-2026-preload">'+ISSUER_PRELOAD+'</script>',1)
    # Main ETF section ends immediately before existing data-accuracy panel.
    p=html.find('<section class="panel" id="etf-tracker-panel"')
    q=html.find('<section class="panel" id="etf-audit-panel"',p)
    if p<0 or q<=p:raise ValueError('ETF section end anchor absent')
    close=html.rfind('</section>',p,q)
    if close<0:raise ValueError('ETF close not found')
    html=html[:close]+AMUNDI_PANEL+'\n'+html[close:]
    html=html.replace(AMUNDI_PANEL,AMUNDI_PANEL+'\n'+ISSUER_PANEL,1)
    # Insert workbook evidence into existing Data Quality / source audit panel.
    q=html.find('<section class="panel" id="etf-audit-panel"')
    close=html.find('</section>',q)
    if q<0 or close<0:raise ValueError('ETF data-accuracy panel absent')
    html=html[:close]+AUDIT_SUMMARY+'\n'+html[close:]
    html=html.replace('</head>','<style id="mt-etf-audit-amundi-css">'+AMUNDI_CSS+'</style>\n</head>',1)
    if html.count('</body>')!=1:raise ValueError('Invalid HTML body marker')
    html=html.replace('</body>','<script id="mt-etf-amundi-reference-js">'+AMUNDI_JS+'</script>\n</body>',1)
    html=html.replace('</body>','<script id="mt-etf-issuer-reference-js">'+ISSUER_JS+'</script>\n</body>',1)
    return html

def validate_snapshot(html: str) -> tuple[int,int,int]:
    """Preserve the original market-data publication guard verbatim in effect."""
    import datetime as dt
    import json
    marker = 'window.MT_DATA = '
    if marker not in html:
        raise ValueError('Missing embedded market data')
    try:
        raw = html.split(marker, 1)[1].split(';</script>', 1)[0]
        data = json.loads(raw)
    except Exception as exc:
        raise ValueError(f'Cannot decode embedded data: {exc}') from exc
    if data.get('demo') is not False:
        raise ValueError('Demo or unverified data; refusing to publish')
    q = data.get('quotes') or []
    obs = len(data.get('history') or [])
    if len(q) < 12 or obs < 150:
        raise ValueError('Too few actual market data observations; refusing to publish')
    now = dt.datetime.now(dt.timezone.utc)
    stamps = []
    for item in q:
        try:
            stamp = dt.datetime.strptime(item['asOf'], '%Y-%m-%d %H:%M UTC').replace(tzinfo=dt.timezone.utc)
            stamps.append(stamp)
        except (KeyError, ValueError, TypeError):
            pass
    if not stamps or max(stamps) < now - dt.timedelta(days=7):
        raise ValueError('Prices older than 7 days; refusing to publish')
    print(f"Snapshot verified: {len(q)} instruments, {obs} observations; "
          f"latest quote {max(stamps).isoformat()}, {len(data.get('warnings') or [])} warnings")
    return len(q),obs,len(data.get('warnings') or [])


def main() -> int:
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('html',type=pathlib.Path,help='Published terminal.html generated by build_terminal.py')
    args=p.parse_args()
    src = args.html.read_text(encoding='utf-8')
    modified,removed,styled = polish(src)
    before=snapshot_data_hash(modified)
    modified=add_ishares_screenshots(modified)
    modified=add_audit_and_amundi(modified)
    if snapshot_data_hash(modified)!=before: raise ValueError("Original market data changed")
    # Do not change terminal.html if market data fail the original publication checks.
    validate_snapshot(modified)
    if modified != src:
        args.html.write_text(modified,encoding='utf-8')
    print(f"iShares screen catalogue: {ISHARES_REFERENCE_COUNT} dated records included; "
          "bid-offer spread tile removed; live quote universe unchanged")
    print(f"Layout checked: ETF lending panel removed={removed}; "
          f"table layouts aligned={styled}; market data unchanged")
    return 0

if __name__ == '__main__':
    try:sys.exit(main())
    except Exception as exc:
        print('ERROR: '+str(exc),file=sys.stderr)
        sys.exit(1)
